public enum Status {
    CREATED(1),
    RUNNING(2),
    PAUSED(3),
    FINISHED(4),
    ARCHIVED(5),
    MODERATION_READY(6),
    MODERATING(7),
    REJECTED(8);

    private final Integer id;

    Status(Integer id) {
        this.id = id;
    }

    public Integer getId() {
        return id;
    }

    public static Status valueOf(int id) {
        for (Status status : Status.values()) {
            if (status.getId() == id) {
                return status;
            }
        }
        throw new IllegalArgumentException("No enum constant with id " + id);
    }
}

