["public class CircularMatrixSearch {

    public static boolean search(int[][] mat, int num) {
        int n = mat.length;
        int low = 0;
        int high = n * n - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int midValue = mat[mid / n][mid % n];

            if (midValue == num) {
                return true;
            }

            // If midValue is smaller, search in the larger half
            if (midValue < num) {
                low = mid + 1;
            } else { // If midValue is larger, search in the smaller half
                high = mid - 1;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        int[][] mat = {
            {10, 20, 30, 40},
            {15, 25, 35, 45},
            {28, 29, 37, 49},
            {33, 34, 38, 50}
        };

        System.out.println(search(mat, 22)); // false
        System.out.println(search(mat, 29)); // true
    }
}

public static boolean search(int[][] mat, int num) {
    int n = mat.length;
    int low = 0;
    int high = n * n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        int midValue = mat[mid / n][mid % n];
        if (midValue == num) {
            return true;
        }
        // If midValue is smaller, search in the larger half
        if (midValue < num) {
            low = mid + 1;
        } else { // If midValue is larger, search in the smaller half
            high = mid - 1;
        }
    }
    return false;
}
public static void main(String[] args) {
